+            assert_eq!(report.status, TurnStatus::Completed);
+            assert!(
+                report.calls[0].output.contains(expected),
+                "{}",
+                report.calls[0].output
+            );
+            assert!(runtime.pending_approvals().is_empty());
+            while let Ok(event) = events.try_recv() {
